// Lembretes no modulo de Agendamentos do Chat Master (owner, 2026-11-15): uma acao por linha; so ha chamada quando algo difere.
const cfg = { textos: { lembrete_dia: "{{BV:textos.lembrete_dia}}", lembrete_hora: "{{BV:textos.lembrete_hora}}" }, user_id: '{{BV:chatmaster.user_id}}',
  wid: '{{BV:chatmaster.whatsapp_id}}', fila: '{{BV:chatmaster.queue_id}}', antecedencia_min_s: {{BV:mensagens.antecedencia_min_s}},
  etiquetas: { confirmado: {{BV:chatmaster.etiquetas.confirmado}}, cancelado: {{BV:chatmaster.etiquetas.cancelado}} } };
const linhas = $input.all().map((x) => x.json);
return bvMSincPlano(linhas, new Date(), cfg).map((p, k) => ({ json: { ...p, tentativas: linhas[k].tentativas, reserva: linhas[k].reserva }, pairedItem: k }));

