// Retomada de agendamento abandonado (owner, 2026-11-16): uma mensagem por conversa reivindicada. TESTE: so envia de verdade para
// teste.contatos_escrita; os demais sao simulados (a mensagem e gravada, nada vai ao WhatsApp).
const cfg = { wid: '{{BV:chatmaster.whatsapp_id}}', fila: '{{BV:chatmaster.queue_id}}', textos: { retomada_confirmar: "{{BV:textos.retomada_confirmar}}", retomada_continuar: "{{BV:textos.retomada_continuar}}" } };
const dig = (s) => String(s || '').replace(/\D/g, '');
const escrita = {{BV:teste.contatos_escrita}}.map(dig);
return $input.all().map((x) => x.json).filter((l) => l.contato_id != null).map((l, k) => {
  const r = bvMRetomada(l, cfg);
  const simulado = '{{BV:ambiente}}' === 'integracao' && !escrita.includes(dig(l.telefone));
  return { json: { contato_id: l.contato_id, texto: r.texto, req: r.req, simulado }, pairedItem: k };
});

const p = $('Montar retomada').item.json;
const st = p.simulado ? 200 : Number($input.item.json.statusCode || 0); // 0 = sem resposta
const ok = st >= 200 && st < 300;
// a conversa ja foi marcada (retomada_em): falha nao repete, so fica registrada
return { json: { contato_id: p.contato_id, texto: ok ? p.texto : null, code: ok ? null : (st ? `HTTP_${st}` : 'SEM_RESPOSTA'), status: st } };
